mapper.select:
select 
from hr_health_certificate_approval_start_outbox
where certificate_id = #{certificateId}
  and business_round = #{businessRound}
limit 1

mapper.update:
update hr_health_certificate_approval_start_outbox
set status = 'SUBMITTING', next_retry_time = null,
    version = version + 1, update_time = sysdate()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and version = #{version}

update hr_health_certificate_approval_start_outbox
set status = 'RETRY', retry_count = #{retryCount},
    next_retry_time = #{nextRetryTime},
    last_http_status = #{lastHttpStatus},
    last_error_code = #{lastErrorCode},
    last_error_message = #{lastErrorMessage},
    version = version + 1, update_time = sysdate()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and version = #{version}

update hr_health_certificate_approval_start_outbox
set status = 'SUCCEEDED', next_retry_time = null,
    last_error_code = null, last_error_message = null,
    completed_time = sysdate(), version = version + 1,
    update_time = sysdate()
where outbox_id = #{outboxId}
  and status = #{expectedStatus}
  and version = #{version}
